import{_ as o,o as t,c as a,a5 as i}from"./chunks/framework.CsGesDJn.js";const g=JSON.parse('{"title":"Plan — Sign In with Google OAuth","description":"","frontmatter":{},"headers":[],"relativePath":"feature/authentication/3-2-3-sign-in-with-google-oauth/plan.md","filePath":"feature/authentication/3-2-3-sign-in-with-google-oauth/plan.md"}'),n={name:"feature/authentication/3-2-3-sign-in-with-google-oauth/plan.md"};function c(l,e,r,d,h,s){return t(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="plan-—-sign-in-with-google-oauth" tabindex="-1">Plan — Sign In with Google OAuth <a class="header-anchor" href="#plan-—-sign-in-with-google-oauth" aria-label="Permalink to &quot;Plan — Sign In with Google OAuth&quot;">​</a></h1><p>&gt; <a href="./spec.html">spec.md</a> — Đăng nhập Google OAuth, backend-driven redirect flow.</p><h2 id="bug-đa-đieu-tra-fix" tabindex="-1">Bug đã điều tra + fix <a class="header-anchor" href="#bug-đa-đieu-tra-fix" aria-label="Permalink to &quot;Bug đã điều tra + fix&quot;">​</a></h2><p>Flow cũ KHÔNG chạy vì <code>GoogleOAuthService.fetchProfile()</code> gửi token-exchange request dạng JSON (<code>body(Map.of(...))</code>) tới <code>https://oauth2.googleapis.com/token</code>. Google <strong>bắt buộc</strong> body <code>application/x-www-form-urlencoded</code>; RestClient chỉ tự convert form cho <code>MultiValueMap</code>, không cho plain <code>Map</code> → request bị Google reject.</p><p><strong>Fix</strong>: chuyển sang <code>MultiValueMap</code> + <code>.contentType(MediaType.APPLICATION_FORM_URLENCODED)</code>.</p><h2 id="ky-thuat" tabindex="-1">Kỹ thuật <a class="header-anchor" href="#ky-thuat" aria-label="Permalink to &quot;Kỹ thuật&quot;">​</a></h2><ul><li><code>OAuthService</code> (base): build consent URL, exchange code, lưu state CSRF Redis <code>oauth:state:{state}</code>, map email→User (merge theo chuẩn hóa email).</li><li><code>GoogleOAuthService.fetchProfile()</code> (đã fix): token exchange form-encoded → gọi <code>/oauth2/v2/userinfo</code> → <code>OAuthProfile(id, email, name, picture)</code>.</li><li>Callback: email đã có User → login (gắn thêm provider Google nếu chưa có); chưa → tạo User <code>emailVerifiedAt=now</code>, không <code>passwordHash</code>.</li><li><strong>2FA (CHỐT 2026-09-20)</strong>: sau khi resolve user + check <code>ACTIVE</code>, nếu <code>twoFactorEnabled=true</code> → sinh <code>twoFactorToken</code> (tái dùng <code>jwtUtil.generateTwoFactorToken</code>) và redirect FE <code>/2fa-verify?twoFactorToken=...</code> <strong>thay vì</strong> cấp accessToken/refresh. Tái dùng endpoint <code>POST /auth/2fa/verify</code> hiện có (provider-agnostic).</li><li>Response không phải JSON: thành công → <code>302</code> redirect FE kèm <code>accessToken</code> trên URL fragment (<code>#token=</code>) + Set-Cookie <code>refreshToken</code>; lỗi → <code>302</code> redirect <code>?error=oauth_failed</code>.</li><li>Ngoài scope Sign In: <code>GoogleOAuthController.link()</code> (<code>GET /oauth/google/link?token=...</code>) — link-mode cho user đã login, thuộc Settings/Account Linking, không thuộc luồng Guest login của FR này.</li></ul><h2 id="luong" tabindex="-1">Luồng <a class="header-anchor" href="#luong" aria-label="Permalink to &quot;Luồng&quot;">​</a></h2><ol><li><code>GET /oauth/google</code> → tạo state → redirect Google consent.</li><li>Callback (<code>/oauth/google/callback</code> hoặc alias <code>/login/oauth2/code/google</code>) → verify state → exchange code (form-encoded) → lấy profile.</li><li>Match email (case-insensitive, đã lowercase/trim) → login/tạo User → nếu 2FA bật thì dừng lại ở bước sinh <code>twoFactorToken</code>, ngược lại issue token + audit.</li></ol><h2 id="rui-ro" tabindex="-1">Rủi ro <a class="header-anchor" href="#rui-ro" aria-label="Permalink to &quot;Rủi ro&quot;">​</a></h2><ul><li>State reuse/replay → state dùng 1 lần, xóa sau khi verify.</li><li>Email trùng account password → merge (không tạo account riêng).</li></ul><h2 id="completion-implementation" tabindex="-1">Completion implementation <a class="header-anchor" href="#completion-implementation" aria-label="Permalink to &quot;Completion implementation&quot;">​</a></h2><p>Add configurable Google redirect URI, public gateway/security callback alias, safe error redirects, atomic state consumption and verified email validation. Frontend consumes and clears the fragment, loads the profile, and clears stale authentication on failure. Update auth locale files in vi/en. Test HTTP callback behavior, provider URL and frontend success/error flows. Verify remote history without rewriting unrelated commits.</p>',13)])])}const p=o(n,[["render",c]]);export{g as __pageData,p as default};
